// Compares the docs and index the page wrote (a dump from browser-measure.mjs) with the same folder generated under
// Node, line by line, ignoring only the Generated At stamp.   node <this file> <dump.json> <folder generated by Node>
import fs from "node:fs";
import path from "node:path";

const [dumpFile, folder] = process.argv.slice(2);
const dump = JSON.parse(fs.readFileSync(dumpFile, "utf8"));
const stamp = (text) => text.replace(/Generated At[^\n]*/g, "Generated At").replace(/"generatedAt":\s*"[^"]*"/g, '"generatedAt":""');
let same = 0; const differ = []; const missing = [];
for (const [pagePath, text] of Object.entries(dump)) {
  const nodePath = path.join(folder, pagePath.replace(/^\/ws\//, ""));
  if (!fs.existsSync(nodePath)) { missing.push(pagePath); continue; }
  if (stamp(fs.readFileSync(nodePath, "utf8")) === stamp(text)) same += 1; else differ.push(pagePath);
}
const nodeCount = fs.readdirSync(path.join(folder, ".live-documentation"), { recursive: true }).filter((p) => !fs.statSync(path.join(folder, ".live-documentation", p)).isDirectory()).length;
console.log(JSON.stringify({ pageFiles: Object.keys(dump).length, nodeFiles: nodeCount, same, differ: differ.slice(0, 10), differCount: differ.length, missing: missing.slice(0, 10) }));
